:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --card-back: #3b3b5c;
  --card-front: #f0f0f5;
  --accent: #ffb347;
  --accent-dark: #e6952e;
  --text: #f0f0f5;
  --matched: #4caf50;
  --radius: 10px;
  --gap: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 18px;
  line-height: 1.5;
  padding: 20px;
}

.game {
  width: 100%;
  max-width: 520px;
  background: var(--surface);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

.game__header {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 20px;
}

.game__title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.game__moves {
  font-size: 1.1rem;
  color: var(--accent);
  font-weight: 600;
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
  margin-bottom: 20px;
}

.card {
  aspect-ratio: 1 / 1;
  border: none;
  border-radius: var(--radius);
  background: var(--card-back);
  cursor: pointer;
  position: relative;
  transition: transform 0.2s ease, background 0.2s ease;
  font-size: 0;
  padding: 0;
  outline: none;
}

.card::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: var(--radius);
  background: var(--card-front);
  opacity: 0;
  transition: opacity 0.2s ease;
}

.card[data-state="flipped"]::after,
.card[data-state="matched"]::after {
  opacity: 1;
  background: var(--color, var(--card-front));
}

.card[data-state="matched"] {
  cursor: default;
  box-shadow: 0 0 0 3px var(--matched);
}

.card:hover:not([data-state="matched"]):not([data-state="flipped"]) {
  transform: scale(1.04);
  background: var(--accent-dark);
}

.card:focus-visible {
  box-shadow: 0 0 0 3px var(--accent);
  z-index: 1;
}

.card:active:not([data-state="matched"]):not([data-state="flipped"]) {
  transform: scale(0.97);
}

.game__footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.win-message {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--matched);
  min-height: 1.5em;
}

.btn {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  padding: 10px 20px;
  border: none;
  border-radius: var(--radius);
  background: var(--accent);
  color: var(--bg);
  cursor: pointer;
  transition: background 0.2s ease, transform 0.1s ease;
}

.btn:hover {
  background: var(--accent-dark);
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.96);
}

@media (max-width: 400px) {
  body {
    padding: 12px;
    font-size: 16px;
  }
  .game {
    padding: 16px;
  }
  .board {
    gap: 8px;
  }
  .game__title {
    font-size: 1.3rem;
  }
  .game__footer {
    flex-direction: column;
    align-items: stretch;
  }
  .btn {
    width: 100%;
  }
}

(() => {
  const COLORS = [
    '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
    '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
  ];

  const board = document.getElementById('board');
  const moveCountEl = document.getElementById('moveCount');
  const winMessageEl = document.getElementById('winMessage');
  const newGameBtn = document.getElementById('newGameBtn');

  let firstCard = null;
  let lockBoard = false;
  let moves = 0;
  let matchedPairs = 0;

  function shuffle(arr) {
    const a = arr.slice();
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  function createCard(color, index) {
    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'card';
    card.dataset.state = 'hidden';
    card.dataset.color = color;
    card.style.setProperty('--color', color);
    card.setAttribute('role', 'gridcell');
    card.setAttribute('aria-label', `Card ${index + 1}, hidden`);
    card.addEventListener('click', () => flipCard(card));
    return card;
  }

  function flipCard(card) {
    if (lockBoard || card.dataset.state !== 'hidden') return;

    card.dataset.state = 'flipped';
    card.setAttribute('aria-label', `Card, color ${card.dataset.color}`);

    if (!firstCard) {
      firstCard = card;
      return;
    }

    moves++;
    moveCountEl.textContent = moves;
    lockBoard = true;

    if (firstCard.dataset.color === card.dataset.color) {
      firstCard.dataset.state = 'matched';
      card.dataset.state = 'matched';
      firstCard.setAttribute('aria-label', 'Matched card');
      card.setAttribute('aria-label', 'Matched card');
      matchedPairs++;
      resetTurn();
      if (matchedPairs === COLORS.length) {
        winMessageEl.textContent = `You won in ${moves} moves!`;
      }
    } else {
      setTimeout(() => {
        firstCard.dataset.state = 'hidden';
        card.dataset.state = 'hidden';
        firstCard.setAttribute('aria-label', `Card, hidden`);
        card.setAttribute('aria-label', `Card, hidden`);
        resetTurn();
      }, 800);
    }
  }

  function resetTurn() {
    firstCard = null;
    lockBoard = false;
  }

  function initGame() {
    board.innerHTML = '';
    firstCard = null;
    lockBoard = false;
    moves = 0;
    matchedPairs = 0;
    moveCountEl.textContent = '0';
    winMessageEl.textContent = '';

    const deck = shuffle([...COLORS, ...COLORS]);
    deck.forEach((color, i) => board.appendChild(createCard(color, i)));
  }

  newGameBtn.addEventListener('click', initGame);
  initGame();
})();
